@js:
var result = [];
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "http://www.cntnn.com"; 
var tag = java.ajax(baseUrl);
if (tag) {
    a = org.jsoup.Jsoup.parse(tag).select(".nav li a");    
    push("🔥排行榜单🔥",null, 1);
    push("全本小说",`/quanben/html/{{page}}/`,0.33);
    push("小说排行",`/rank/`,0.33);
    push("总排行榜",`/rank/allvisit/`,0.33);
    push("月排行榜",`/rank/monthvisit/`,0.33);
    push("周排行榜",`/rank/weekvisit/`,0.33);
    push("总收藏榜",`/rank/goodnum/`,0.33);

    push("🔥分类小说🔥", null, 1);
    for (i in a) {
        title = a[i].text();
        url = a[i].attr("href");
        size = 0.33;
        title = String(title).replace(/\s/g, ""); 
        url = baseUrl + String(url).replace(/\/\d+\/$/, "/") + "{{page}}/"; 
        push(title, url, size);
    }
} 
JSON.stringify(result);

ruleToc.chapterList:
@js:
let v = [],
		list = [];
JSON.parse(result).list.map($=>{

//分卷判定
		V = $.name;
		if(v[v.length-1]!=V&&!/^\s*$/.test(V)){
				v.push(V)
				list.push({
						name: '📖['+V+']📖',
						volume: true
					})
			}

$.bookChapters.map($=>{
		return list.push({
				name: $.name,
				url: `https://readbook-service-freebook.cread.com/cx/itf/chapterRead?bookId=${$.bookid}&chapterId=${$.id}`,
				info: `章节字数：${$.wordCount}　更新时间：${$.updateDate}`
			});
	});
});
v.length<2?list.filter($=>!$.volume):list

